    n = num_partitions
    dst_list = sorted(set(dsts))

    def edge_cost(u, v):
        c = G[u][v].get("cost")
        return c if c is not None else float("inf")

    def build_tree(first_dst=None, farthest_first=False):
        """One greedy Steiner run; returns (edge_set, dst->path map, ok)."""
        used = set()
        paths = {}
        remaining = list(dst_list)
        if first_dst is not None and first_dst in remaining:
            remaining.remove(first_dst)
            remaining.insert(0, first_dst)

        def tree_weight(u, v, data):
            if (u, v) in used:
                return 0.0
            c = data.get("cost")
            return c if c is not None else float("inf")

        while remaining:
            if farthest_first:
                # serve most expensive (farthest) destination first
                best = None  # (dist, dst, path) -> keep max dist
                for dst in remaining:
                    try:
                        dist, path = nx.single_source_dijkstra(h, src, dst, weight=tree_weight)
                    except (nx.NetworkXNoPath, nx.NodeNotFound):
                        continue
                    if best is None or dist > best[0]:
                        best = (dist, dst, path)
            else:
                best = None  # keep min dist
                for dst in remaining:
                    try:
                        dist, path = nx.single_source_dijkstra(h, src, dst, weight=tree_weight)
                    except (nx.NetworkXNoPath, nx.NodeNotFound):
                        continue
                    if best is None or dist < best[0]:
                        best = (dist, dst, path)

